import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].lower().split('__')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[path[-1]] = _coerce(value, defaults.get(path[-1]))
    return config

def _coerce(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ['true', '1', 'yes']
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for {value}')

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'key': 'value'}
    assert load_config(defaults) == {'key': 'value'}

def test_toml():
    defaults = {'key': 'value'}
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    assert load_config(defaults, 'config.toml') == {'key': 'toml_value'}

def test_env():
    defaults = {'key': 'value'}
    os.environ['APP__KEY'] = 'env_value'
    assert load_config(defaults, env_prefix='APP__') == {'key': 'env_value'}

def test_precedence():
    defaults = {'key': 'value'}
    with open('config.toml', 'wb') as f:
        f.write(b'key = "toml_value"')
    os.environ['APP__KEY'] = 'env_value'
    assert load_config(defaults, 'config.toml', env_prefix='APP__') == {'key': 'env_value'}

def test_coercion():
    defaults = {'int_key': 1, 'float_key': 1.0, 'bool_key': True, 'str_key': 'string'}
    os.environ['APP__INT_KEY'] = '2'
    os.environ['APP__FLOAT_KEY'] = '2.0'
    os.environ['APP__BOOL_KEY'] = 'false'
    os.environ['APP__STR_KEY'] = 'new_string'
    assert load_config(defaults, env_prefix='APP__') == {'int_key': 2, 'float_key': 2.0, 'bool_key': False, 'str_key': 'new_string'}

def test_error():
    defaults = {'key': 1}
    os.environ['APP__KEY'] = 'value'
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

